-- =============================================================================
-- 01_ref.sql — Reference / lookup tables (schema: ref)
--
-- Every closed list of values is a table, never a PG enum or a free-text column,
-- so values are data (addable without DDL), carry labels, and can be retired.
--
-- Standard lookup shape:
--   id          smallint identity   surrogate key used by FKs
--   code        citext UNIQUE       stable machine key used by application code
--   label       text                human-readable label
--   is_active   boolean             retire a value without breaking history
--   sort_order  smallint            UI ordering
-- =============================================================================

SET client_encoding = 'UTF8';   -- files are UTF-8; psql on Windows may default to WIN1252

SET search_path = ref, public;

-- ---------------------------------------------------------------- geography --
CREATE TABLE ref.country (
  id          smallint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  iso2        char(2)  NOT NULL UNIQUE CHECK (iso2 ~ '^[A-Z]{2}$'),
  iso3        char(3)  NOT NULL UNIQUE CHECK (iso3 ~ '^[A-Z]{3}$'),
  name        text     NOT NULL UNIQUE,
  dial_code   varchar(6) NOT NULL CHECK (dial_code ~ '^\+[0-9]{1,4}$'),
  is_active   boolean  NOT NULL DEFAULT true
);

CREATE TABLE ref.state_province (
  id          int GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  country_id  smallint NOT NULL REFERENCES ref.country(id),
  code        varchar(10) NOT NULL,          -- ISO 3166-2 subdivision suffix, e.g. 'HR'
  name        text NOT NULL,
  is_active   boolean NOT NULL DEFAULT true,
  UNIQUE (country_id, code),
  UNIQUE (country_id, name)
);

CREATE TABLE ref.city (
  id                 int GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  state_province_id  int NOT NULL REFERENCES ref.state_province(id),
  name               text NOT NULL,
  is_active          boolean NOT NULL DEFAULT true,
  UNIQUE (state_province_id, name)
);

CREATE TABLE ref.language (
  id          smallint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  code        citext NOT NULL UNIQUE,         -- BCP-47, e.g. 'en', 'hi'
  label       text   NOT NULL,
  is_scheduled_language boolean NOT NULL DEFAULT false,  -- 8th Schedule (DPDP §5(3))
  is_active   boolean NOT NULL DEFAULT true,
  sort_order  smallint NOT NULL DEFAULT 0
);

-- -------------------------------------------------------------- generic lookups
-- (identical shape; kept as explicit DDL for readability and Django mapping)

CREATE TABLE ref.gender              (id smallint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, code citext NOT NULL UNIQUE, label text NOT NULL, is_active boolean NOT NULL DEFAULT true, sort_order smallint NOT NULL DEFAULT 0);
CREATE TABLE ref.blood_group         (id smallint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, code citext NOT NULL UNIQUE, label text NOT NULL, is_active boolean NOT NULL DEFAULT true, sort_order smallint NOT NULL DEFAULT 0);
CREATE TABLE ref.contact_purpose     (id smallint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, code citext NOT NULL UNIQUE, label text NOT NULL, is_active boolean NOT NULL DEFAULT true, sort_order smallint NOT NULL DEFAULT 0);
CREATE TABLE ref.contact_channel     (id smallint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, code citext NOT NULL UNIQUE, label text NOT NULL, is_active boolean NOT NULL DEFAULT true, sort_order smallint NOT NULL DEFAULT 0);
CREATE TABLE ref.address_type        (id smallint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, code citext NOT NULL UNIQUE, label text NOT NULL, is_active boolean NOT NULL DEFAULT true, sort_order smallint NOT NULL DEFAULT 0);
CREATE TABLE ref.relationship_type   (id smallint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, code citext NOT NULL UNIQUE, label text NOT NULL, is_active boolean NOT NULL DEFAULT true, sort_order smallint NOT NULL DEFAULT 0);
CREATE TABLE ref.id_document_type    (id smallint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, code citext NOT NULL UNIQUE, label text NOT NULL, is_active boolean NOT NULL DEFAULT true, sort_order smallint NOT NULL DEFAULT 0);
CREATE TABLE ref.storage_backend     (id smallint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, code citext NOT NULL UNIQUE, label text NOT NULL, is_active boolean NOT NULL DEFAULT true, sort_order smallint NOT NULL DEFAULT 0);

-- organisation
CREATE TABLE ref.org_unit_type (
  id          smallint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  code        citext NOT NULL UNIQUE,         -- UNIVERSITY, SCHOOL, DEPARTMENT, CENTRAL_DEPARTMENT, SECTION ...
  label       text   NOT NULL,
  is_academic boolean NOT NULL,               -- academic vs administrative branch
  is_active   boolean NOT NULL DEFAULT true,
  sort_order  smallint NOT NULL DEFAULT 0
);

-- people
CREATE TABLE ref.principal_kind      (id smallint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, code citext NOT NULL UNIQUE, label text NOT NULL, is_active boolean NOT NULL DEFAULT true, sort_order smallint NOT NULL DEFAULT 0);
CREATE TABLE ref.employee_category   (id smallint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, code citext NOT NULL UNIQUE, label text NOT NULL, is_active boolean NOT NULL DEFAULT true, sort_order smallint NOT NULL DEFAULT 0);
CREATE TABLE ref.employment_type     (id smallint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, code citext NOT NULL UNIQUE, label text NOT NULL, is_active boolean NOT NULL DEFAULT true, sort_order smallint NOT NULL DEFAULT 0);
CREATE TABLE ref.employment_status (id smallint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, code citext NOT NULL UNIQUE, label text NOT NULL, is_current_member boolean NOT NULL, is_active boolean NOT NULL DEFAULT true, sort_order smallint NOT NULL DEFAULT 0);
CREATE TABLE ref.student_status (id smallint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, code citext NOT NULL UNIQUE, label text NOT NULL, is_current_member boolean NOT NULL, is_active boolean NOT NULL DEFAULT true, sort_order smallint NOT NULL DEFAULT 0);

-- Functional area of work (Academics, Finance, HR, IT...) — cuts across
-- departments; independent of where someone sits in the org tree.
CREATE TABLE ref.job_function (id smallint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, code citext NOT NULL UNIQUE, label text NOT NULL, is_active boolean NOT NULL DEFAULT true, sort_order smallint NOT NULL DEFAULT 0);

-- What the person actually does (Teaching, Research, Recruitment, Payroll
-- Processing...) — distinct from Designation, which is the formal title/rank.
CREATE TABLE ref.job_role (id smallint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, code citext NOT NULL UNIQUE, label text NOT NULL, is_active boolean NOT NULL DEFAULT true, sort_order smallint NOT NULL DEFAULT 0);

-- REPORTING = direct/line manager; REVIEWING = second-level manager for appraisals.
CREATE TABLE ref.reporting_line_type (id smallint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, code citext NOT NULL UNIQUE, label text NOT NULL, is_active boolean NOT NULL DEFAULT true, sort_order smallint NOT NULL DEFAULT 0);

CREATE TABLE ref.grade (
  id          smallint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  code        citext NOT NULL UNIQUE,         -- O1 .. O10
  label       text   NOT NULL,
  rank        smallint NOT NULL UNIQUE,       -- 1 = most senior
  is_active   boolean NOT NULL DEFAULT true
);

-- academic
CREATE TABLE ref.program_level       (id smallint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, code citext NOT NULL UNIQUE, label text NOT NULL, is_active boolean NOT NULL DEFAULT true, sort_order smallint NOT NULL DEFAULT 0);

-- How a programme divides its duration: SEMESTER, ANNUAL, PROFESSIONAL_YEAR.
CREATE TABLE ref.academic_calendar_type (
  id              smallint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  code            citext NOT NULL UNIQUE,
  label           text   NOT NULL,
  terms_per_year  smallint NOT NULL CHECK (terms_per_year BETWEEN 1 AND 4),
  is_active       boolean NOT NULL DEFAULT true,
  sort_order      smallint NOT NULL DEFAULT 0
);

-- The recurring term slots of a calendar type (SEMESTER: ODD, EVEN; ANNUAL: ANNUAL …).
-- position = order of the slot inside an academic year.
CREATE TABLE ref.term_cycle (
  id                         smallint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  academic_calendar_type_id  smallint NOT NULL REFERENCES ref.academic_calendar_type(id),
  code                       citext NOT NULL UNIQUE,
  label                      text   NOT NULL,
  position                   smallint NOT NULL CHECK (position >= 1),
  is_active                  boolean NOT NULL DEFAULT true,
  UNIQUE (academic_calendar_type_id, position)
);

-- curriculum & delivery
CREATE TABLE ref.course_category       (id smallint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, code citext NOT NULL UNIQUE, label text NOT NULL, is_elective boolean NOT NULL,
                                        parent_category_id smallint REFERENCES ref.course_category(id),   -- sub-category: DSC → DSCC / DSCE
                                        requires_supervision boolean NOT NULL DEFAULT false,              -- project / internship / dissertation: a guide is allocated
                                        is_active boolean NOT NULL DEFAULT true, sort_order smallint NOT NULL DEFAULT 0,
                                        CHECK (parent_category_id IS DISTINCT FROM id));
CREATE TABLE ref.delivery_component    (id smallint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, code citext NOT NULL UNIQUE, label text NOT NULL, is_active boolean NOT NULL DEFAULT true, sort_order smallint NOT NULL DEFAULT 0);  -- LECTURE / TUTORIAL / PRACTICAL (L-T-P)
CREATE TABLE ref.room_type             (id smallint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, code citext NOT NULL UNIQUE, label text NOT NULL, is_active boolean NOT NULL DEFAULT true, sort_order smallint NOT NULL DEFAULT 0);
CREATE TABLE ref.batch_document_type   (id smallint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, code citext NOT NULL UNIQUE, label text NOT NULL, is_active boolean NOT NULL DEFAULT true, sort_order smallint NOT NULL DEFAULT 0);
CREATE TABLE ref.registration_status   (id smallint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, code citext NOT NULL UNIQUE, label text NOT NULL, is_counted boolean NOT NULL, is_active boolean NOT NULL DEFAULT true, sort_order smallint NOT NULL DEFAULT 0);  -- is_counted: still on the roster
CREATE TABLE ref.class_session_status  (id smallint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, code citext NOT NULL UNIQUE, label text NOT NULL, counts_as_held boolean NOT NULL, releases_room boolean NOT NULL DEFAULT false, is_active boolean NOT NULL DEFAULT true, sort_order smallint NOT NULL DEFAULT 0);  -- releases_room: the room hold of that date is freed (cancelled / rescheduled)
CREATE TABLE ref.attendance_status     (id smallint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, code citext NOT NULL UNIQUE, label text NOT NULL, counts_as_present boolean NOT NULL, is_active boolean NOT NULL DEFAULT true, sort_order smallint NOT NULL DEFAULT 0);

-- flexible curriculum (NEP 2020): exits & awards, credit transfer, minors/honours
CREATE TABLE ref.award_type            (id smallint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, code citext NOT NULL UNIQUE, label text NOT NULL, is_active boolean NOT NULL DEFAULT true, sort_order smallint NOT NULL DEFAULT 0);  -- UG certificate / diploma / degree / honours …
CREATE TABLE ref.external_provider_type (id smallint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, code citext NOT NULL UNIQUE, label text NOT NULL, is_active boolean NOT NULL DEFAULT true, sort_order smallint NOT NULL DEFAULT 0);  -- university / MOOC platform / industry
CREATE TABLE ref.credit_transfer_status (id smallint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, code citext NOT NULL UNIQUE, label text NOT NULL, is_accepted boolean NOT NULL, is_active boolean NOT NULL DEFAULT true, sort_order smallint NOT NULL DEFAULT 0);  -- is_accepted: credits count
CREATE TABLE ref.track_type            (id smallint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, code citext NOT NULL UNIQUE, label text NOT NULL, requires_own_program boolean NOT NULL, is_active boolean NOT NULL DEFAULT true, sort_order smallint NOT NULL DEFAULT 0);  -- honours = own programme; minor = another discipline

-- examination
CREATE TABLE ref.evaluation_part       (id smallint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, code citext NOT NULL UNIQUE, label text NOT NULL, is_active boolean NOT NULL DEFAULT true, sort_order smallint NOT NULL DEFAULT 0);  -- INTERNAL (CIE) / EXTERNAL (ESE)
CREATE TABLE ref.assessment_type       (id smallint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, code citext NOT NULL UNIQUE, label text NOT NULL, is_scheduled_exam boolean NOT NULL,
                                        uses_answer_scripts boolean NOT NULL,          -- scheduled AND marked through anonymous scripts (theory papers); false = marked directly by examiners (practical exam, viva)
                                        requires_external_examiner boolean NOT NULL DEFAULT false,  -- marks accepted only once the paper's panel has an external examiner
                                        evaluation_part_id smallint NOT NULL REFERENCES ref.evaluation_part(id),
                                        CHECK (is_scheduled_exam OR NOT uses_answer_scripts),
                                        is_active boolean NOT NULL DEFAULT true, sort_order smallint NOT NULL DEFAULT 0);  -- scheduled exam = has a date sheet, answer scripts, seating
CREATE TABLE ref.exam_session_type     (id smallint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, code citext NOT NULL UNIQUE, label text NOT NULL, is_active boolean NOT NULL DEFAULT true, sort_order smallint NOT NULL DEFAULT 0);
CREATE TABLE ref.exam_attempt_type     (id smallint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, code citext NOT NULL UNIQUE, label text NOT NULL, requires_eligibility boolean NOT NULL, is_active boolean NOT NULL DEFAULT true, sort_order smallint NOT NULL DEFAULT 0);
CREATE TABLE ref.exam_hold_type        (id smallint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, code citext NOT NULL UNIQUE, label text NOT NULL, is_active boolean NOT NULL DEFAULT true, sort_order smallint NOT NULL DEFAULT 0);
CREATE TABLE ref.exam_attendance_status (id smallint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, code citext NOT NULL UNIQUE, label text NOT NULL, is_active boolean NOT NULL DEFAULT true, sort_order smallint NOT NULL DEFAULT 0);
CREATE TABLE ref.ufm_case_status       (id smallint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, code citext NOT NULL UNIQUE, label text NOT NULL, is_terminal boolean NOT NULL, is_active boolean NOT NULL DEFAULT true, sort_order smallint NOT NULL DEFAULT 0);
CREATE TABLE ref.ufm_penalty           (id smallint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, code citext NOT NULL UNIQUE, label text NOT NULL, is_active boolean NOT NULL DEFAULT true, sort_order smallint NOT NULL DEFAULT 0);
CREATE TABLE ref.evaluation_round      (id smallint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, code citext NOT NULL UNIQUE, label text NOT NULL, precedence smallint NOT NULL UNIQUE, is_active boolean NOT NULL DEFAULT true);  -- highest precedence present = the mark that counts
CREATE TABLE ref.result_status         (id smallint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, code citext NOT NULL UNIQUE, label text NOT NULL, is_pass boolean NOT NULL, is_active boolean NOT NULL DEFAULT true, sort_order smallint NOT NULL DEFAULT 0);
CREATE TABLE ref.publication_type      (id smallint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, code citext NOT NULL UNIQUE, label text NOT NULL, is_active boolean NOT NULL DEFAULT true, sort_order smallint NOT NULL DEFAULT 0);
CREATE TABLE ref.revaluation_type      (id smallint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, code citext NOT NULL UNIQUE, label text NOT NULL, is_active boolean NOT NULL DEFAULT true, sort_order smallint NOT NULL DEFAULT 0);
CREATE TABLE ref.revaluation_status    (id smallint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, code citext NOT NULL UNIQUE, label text NOT NULL, is_terminal boolean NOT NULL, is_active boolean NOT NULL DEFAULT true, sort_order smallint NOT NULL DEFAULT 0);

-- student lifecycle, academic calendar, programme attributes, curriculum content,
-- faculty workload, feedback (04d_student_lifecycle.sql)
CREATE TABLE ref.term_registration_status (id smallint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, code citext NOT NULL UNIQUE, label text NOT NULL, is_counted boolean NOT NULL, is_active boolean NOT NULL DEFAULT true, sort_order smallint NOT NULL DEFAULT 0);  -- is_counted: the student is on the term's rolls
CREATE TABLE ref.academic_standing      (id smallint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, code citext NOT NULL UNIQUE, label text NOT NULL, is_promoted boolean NOT NULL, allows_backlog boolean NOT NULL, is_active boolean NOT NULL DEFAULT true, sort_order smallint NOT NULL DEFAULT 0);  -- end-of-term decision: promoted / promoted with backlog / detained
CREATE TABLE ref.study_break_type       (id smallint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, code citext NOT NULL UNIQUE, label text NOT NULL, is_active boolean NOT NULL DEFAULT true, sort_order smallint NOT NULL DEFAULT 0);
CREATE TABLE ref.enrollment_end_reason  (id smallint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, code citext NOT NULL UNIQUE, label text NOT NULL, is_active boolean NOT NULL DEFAULT true, sort_order smallint NOT NULL DEFAULT 0);
CREATE TABLE ref.delivery_mode          (id smallint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, code citext NOT NULL UNIQUE, label text NOT NULL, is_active boolean NOT NULL DEFAULT true, sort_order smallint NOT NULL DEFAULT 0);  -- regular / part-time / distance / online
CREATE TABLE ref.regulatory_body        (id smallint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, code citext NOT NULL UNIQUE, label text NOT NULL, is_active boolean NOT NULL DEFAULT true, sort_order smallint NOT NULL DEFAULT 0);  -- UGC, AICTE, NMC, PCI, BCI ...
CREATE TABLE ref.accreditation_body     (id smallint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, code citext NOT NULL UNIQUE, label text NOT NULL, is_active boolean NOT NULL DEFAULT true, sort_order smallint NOT NULL DEFAULT 0);  -- NAAC, NBA ...
CREATE TABLE ref.calendar_event_type    (id smallint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, code citext NOT NULL UNIQUE, label text NOT NULL, is_non_working boolean NOT NULL, is_active boolean NOT NULL DEFAULT true, sort_order smallint NOT NULL DEFAULT 0);  -- holiday / vacation / registration window / exam period ...
CREATE TABLE ref.bloom_level            (id smallint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, code citext NOT NULL UNIQUE, label text NOT NULL, rank smallint NOT NULL UNIQUE, is_active boolean NOT NULL DEFAULT true);  -- cognitive level of a course outcome
CREATE TABLE ref.program_outcome_type   (id smallint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, code citext NOT NULL UNIQUE, label text NOT NULL, is_active boolean NOT NULL DEFAULT true, sort_order smallint NOT NULL DEFAULT 0);  -- PO / PSO

-- doctoral & research degrees (04e_research.sql)
CREATE TABLE ref.supervisor_role        (id smallint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, code citext NOT NULL UNIQUE, label text NOT NULL, is_principal boolean NOT NULL, allows_external boolean NOT NULL, is_active boolean NOT NULL DEFAULT true, sort_order smallint NOT NULL DEFAULT 0);
CREATE TABLE ref.committee_role         (id smallint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, code citext NOT NULL UNIQUE, label text NOT NULL, is_chair boolean NOT NULL, is_active boolean NOT NULL DEFAULT true, sort_order smallint NOT NULL DEFAULT 0);
CREATE TABLE ref.progress_review_outcome (id smallint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, code citext NOT NULL UNIQUE, label text NOT NULL, is_satisfactory boolean NOT NULL, is_active boolean NOT NULL DEFAULT true, sort_order smallint NOT NULL DEFAULT 0);
CREATE TABLE ref.thesis_status          (id smallint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, code citext NOT NULL UNIQUE, label text NOT NULL, is_terminal boolean NOT NULL, is_active boolean NOT NULL DEFAULT true, sort_order smallint NOT NULL DEFAULT 0);
CREATE TABLE ref.thesis_examiner_role   (id smallint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, code citext NOT NULL UNIQUE, label text NOT NULL, is_external boolean NOT NULL, is_active boolean NOT NULL DEFAULT true, sort_order smallint NOT NULL DEFAULT 0);
CREATE TABLE ref.examiner_recommendation (id smallint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, code citext NOT NULL UNIQUE, label text NOT NULL, is_accept boolean NOT NULL, blocks_viva boolean NOT NULL, is_active boolean NOT NULL DEFAULT true, sort_order smallint NOT NULL DEFAULT 0);

-- question papers & certificates (04f_exam_papers_certificates.sql)
CREATE TABLE ref.paper_setter_role      (id smallint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, code citext NOT NULL UNIQUE, label text NOT NULL, is_active boolean NOT NULL DEFAULT true, sort_order smallint NOT NULL DEFAULT 0);  -- setter / moderator
CREATE TABLE ref.question_paper_status  (id smallint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, code citext NOT NULL UNIQUE, label text NOT NULL, is_moderated boolean NOT NULL, is_approved boolean NOT NULL, is_active boolean NOT NULL DEFAULT true, sort_order smallint NOT NULL DEFAULT 0);
CREATE TABLE ref.certificate_type       (id smallint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, code citext NOT NULL UNIQUE, label text NOT NULL, requires_award boolean NOT NULL, requires_closed_enrollment boolean NOT NULL, is_single_issue boolean NOT NULL, is_active boolean NOT NULL DEFAULT true, sort_order smallint NOT NULL DEFAULT 0);

-- identity & access
CREATE TABLE ref.account_status      (id smallint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, code citext NOT NULL UNIQUE, label text NOT NULL, can_login boolean NOT NULL, is_active boolean NOT NULL DEFAULT true, sort_order smallint NOT NULL DEFAULT 0);
CREATE TABLE ref.mfa_factor_type     (id smallint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, code citext NOT NULL UNIQUE, label text NOT NULL, is_active boolean NOT NULL DEFAULT true, sort_order smallint NOT NULL DEFAULT 0);
CREATE TABLE ref.otp_purpose         (id smallint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, code citext NOT NULL UNIQUE, label text NOT NULL, is_active boolean NOT NULL DEFAULT true, sort_order smallint NOT NULL DEFAULT 0);
CREATE TABLE ref.auth_event_type     (id smallint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, code citext NOT NULL UNIQUE, label text NOT NULL, is_active boolean NOT NULL DEFAULT true, sort_order smallint NOT NULL DEFAULT 0);
CREATE TABLE ref.auth_failure_reason (id smallint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, code citext NOT NULL UNIQUE, label text NOT NULL, is_active boolean NOT NULL DEFAULT true, sort_order smallint NOT NULL DEFAULT 0);
CREATE TABLE ref.session_revoke_reason (id smallint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, code citext NOT NULL UNIQUE, label text NOT NULL, is_active boolean NOT NULL DEFAULT true, sort_order smallint NOT NULL DEFAULT 0);
CREATE TABLE ref.lockout_reason      (id smallint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, code citext NOT NULL UNIQUE, label text NOT NULL, is_active boolean NOT NULL DEFAULT true, sort_order smallint NOT NULL DEFAULT 0);

-- privacy (DPDP)
CREATE TABLE ref.legal_basis         (id smallint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, code citext NOT NULL UNIQUE, label text NOT NULL, dpdp_section text NOT NULL, requires_consent boolean NOT NULL, is_active boolean NOT NULL DEFAULT true, sort_order smallint NOT NULL DEFAULT 0);
CREATE TABLE ref.data_category       (id smallint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, code citext NOT NULL UNIQUE, label text NOT NULL, is_sensitive boolean NOT NULL DEFAULT false, is_active boolean NOT NULL DEFAULT true, sort_order smallint NOT NULL DEFAULT 0);
CREATE TABLE ref.erasure_action      (id smallint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, code citext NOT NULL UNIQUE, label text NOT NULL, is_active boolean NOT NULL DEFAULT true, sort_order smallint NOT NULL DEFAULT 0);
CREATE TABLE ref.consent_channel     (id smallint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, code citext NOT NULL UNIQUE, label text NOT NULL, is_active boolean NOT NULL DEFAULT true, sort_order smallint NOT NULL DEFAULT 0);
CREATE TABLE ref.verification_method (id smallint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, code citext NOT NULL UNIQUE, label text NOT NULL, is_active boolean NOT NULL DEFAULT true, sort_order smallint NOT NULL DEFAULT 0);
CREATE TABLE ref.dpr_request_type    (id smallint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, code citext NOT NULL UNIQUE, label text NOT NULL, dpdp_section text NOT NULL, response_days smallint NOT NULL CHECK (response_days > 0), is_active boolean NOT NULL DEFAULT true, sort_order smallint NOT NULL DEFAULT 0);
CREATE TABLE ref.dpr_status          (id smallint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, code citext NOT NULL UNIQUE, label text NOT NULL, is_terminal boolean NOT NULL, is_active boolean NOT NULL DEFAULT true, sort_order smallint NOT NULL DEFAULT 0);
CREATE TABLE ref.breach_severity     (id smallint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, code citext NOT NULL UNIQUE, label text NOT NULL, is_active boolean NOT NULL DEFAULT true, sort_order smallint NOT NULL DEFAULT 0);
CREATE TABLE ref.breach_status       (id smallint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, code citext NOT NULL UNIQUE, label text NOT NULL, is_terminal boolean NOT NULL, is_active boolean NOT NULL DEFAULT true, sort_order smallint NOT NULL DEFAULT 0);

-- audit
CREATE TABLE ref.audit_action        (id smallint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, code citext NOT NULL UNIQUE, label text NOT NULL, is_active boolean NOT NULL DEFAULT true, sort_order smallint NOT NULL DEFAULT 0);
-- seeded here: audit.capture() (07) needs these rows before any other insert
INSERT INTO ref.audit_action (code, label, sort_order) VALUES ('INSERT','Insert',1),('UPDATE','Update',2),('DELETE','Delete',3);


-- resource & facility management (06d_facility.sql)
CREATE TABLE ref.building_kind         (id smallint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, code citext NOT NULL UNIQUE, label text NOT NULL, is_active boolean NOT NULL DEFAULT true, sort_order smallint NOT NULL DEFAULT 0);  -- BUILDING / OPEN_AREA / PARKING
CREATE TABLE ref.room_use              (id smallint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, code citext NOT NULL UNIQUE, label text NOT NULL,
                                        is_bookable boolean NOT NULL DEFAULT true,      -- may be booked through facility.booking_request
                                        is_guest_room boolean NOT NULL DEFAULT false,   -- occupied through facility.guest_stay
                                        is_parking_zone boolean NOT NULL DEFAULT false, -- holds facility.parking_permit rows
                                        is_active boolean NOT NULL DEFAULT true, sort_order smallint NOT NULL DEFAULT 0);  -- FICM-style room-use classification
CREATE TABLE ref.hold_type             (id smallint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, code citext NOT NULL UNIQUE, label text NOT NULL,
                                        source_table text NOT NULL,                     -- 'schema.table' the hold is written from
                                        default_setup_minutes smallint NOT NULL DEFAULT 0 CHECK (default_setup_minutes >= 0),
                                        default_teardown_minutes smallint NOT NULL DEFAULT 0 CHECK (default_teardown_minutes >= 0),
                                        is_active boolean NOT NULL DEFAULT true, sort_order smallint NOT NULL DEFAULT 0);
CREATE TABLE ref.booking_purpose       (id smallint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, code citext NOT NULL UNIQUE, label text NOT NULL,
                                        hold_type_id smallint NOT NULL REFERENCES ref.hold_type(id),   -- which class of use (and priority) a booking of this purpose is
                                        is_active boolean NOT NULL DEFAULT true, sort_order smallint NOT NULL DEFAULT 0);
CREATE TABLE ref.facility_resource_kind (id smallint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, code citext NOT NULL UNIQUE, label text NOT NULL, is_active boolean NOT NULL DEFAULT true, sort_order smallint NOT NULL DEFAULT 0);  -- ROOM / ASSET / VEHICLE / GUEST_ROOM / PARKING / KEY
CREATE TABLE ref.booking_restriction_reason (id smallint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, code citext NOT NULL UNIQUE, label text NOT NULL, is_active boolean NOT NULL DEFAULT true, sort_order smallint NOT NULL DEFAULT 0);
CREATE TABLE ref.booking_cancel_reason (id smallint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, code citext NOT NULL UNIQUE, label text NOT NULL,
                                        is_system boolean NOT NULL DEFAULT false,   -- set by a trigger / job, not chosen by a person
                                        is_active boolean NOT NULL DEFAULT true, sort_order smallint NOT NULL DEFAULT 0);
CREATE TABLE ref.room_service_type     (id smallint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, code citext NOT NULL UNIQUE, label text NOT NULL, is_active boolean NOT NULL DEFAULT true, sort_order smallint NOT NULL DEFAULT 0);
CREATE TABLE ref.asset_type            (id smallint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, code citext NOT NULL UNIQUE, label text NOT NULL, is_active boolean NOT NULL DEFAULT true, sort_order smallint NOT NULL DEFAULT 0);
CREATE TABLE ref.asset_condition       (id smallint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, code citext NOT NULL UNIQUE, label text NOT NULL, is_serviceable boolean NOT NULL, is_active boolean NOT NULL DEFAULT true, sort_order smallint NOT NULL DEFAULT 0);
CREATE TABLE ref.work_order_category   (id smallint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, code citext NOT NULL UNIQUE, label text NOT NULL, is_active boolean NOT NULL DEFAULT true, sort_order smallint NOT NULL DEFAULT 0);
CREATE TABLE ref.work_order_priority   (id smallint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, code citext NOT NULL UNIQUE, label text NOT NULL,
                                        resolve_within interval NOT NULL,           -- SLA from the report
                                        rank smallint NOT NULL UNIQUE, is_active boolean NOT NULL DEFAULT true);
CREATE TABLE ref.work_order_status     (id smallint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, code citext NOT NULL UNIQUE, label text NOT NULL,
                                        is_terminal boolean NOT NULL, is_active boolean NOT NULL DEFAULT true, sort_order smallint NOT NULL DEFAULT 0);
CREATE TABLE ref.maintenance_type      (id smallint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, code citext NOT NULL UNIQUE, label text NOT NULL, is_active boolean NOT NULL DEFAULT true, sort_order smallint NOT NULL DEFAULT 0);
CREATE TABLE ref.guest_category        (id smallint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, code citext NOT NULL UNIQUE, label text NOT NULL,
                                        guest_kind citext NOT NULL CHECK (guest_kind IN ('EMPLOYEE','STUDENT','EXTERNAL','ANY')),   -- who may be booked under it
                                        is_complimentary boolean NOT NULL DEFAULT false,   -- no tariff applies
                                        is_active boolean NOT NULL DEFAULT true, sort_order smallint NOT NULL DEFAULT 0);
CREATE TABLE ref.event_kind            (id smallint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, code citext NOT NULL UNIQUE, label text NOT NULL, is_active boolean NOT NULL DEFAULT true, sort_order smallint NOT NULL DEFAULT 0);
CREATE TABLE ref.key_kind              (id smallint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, code citext NOT NULL UNIQUE, label text NOT NULL, is_master boolean NOT NULL DEFAULT false, is_active boolean NOT NULL DEFAULT true, sort_order smallint NOT NULL DEFAULT 0);
CREATE TABLE ref.parking_permit_type   (id smallint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, code citext NOT NULL UNIQUE, label text NOT NULL, is_active boolean NOT NULL DEFAULT true, sort_order smallint NOT NULL DEFAULT 0);
CREATE TABLE ref.vehicle_type          (id smallint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, code citext NOT NULL UNIQUE, label text NOT NULL, is_passenger boolean NOT NULL DEFAULT true, is_active boolean NOT NULL DEFAULT true, sort_order smallint NOT NULL DEFAULT 0);
CREATE TABLE ref.fuel_type             (id smallint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, code citext NOT NULL UNIQUE, label text NOT NULL, is_active boolean NOT NULL DEFAULT true, sort_order smallint NOT NULL DEFAULT 0);
CREATE TABLE ref.licence_class         (id smallint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, code citext NOT NULL UNIQUE, label text NOT NULL, rank smallint NOT NULL UNIQUE, is_active boolean NOT NULL DEFAULT true);  -- higher rank covers the lower ones
CREATE TABLE ref.vehicle_document_type (id smallint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, code citext NOT NULL UNIQUE, label text NOT NULL, is_mandatory_for_trip boolean NOT NULL DEFAULT true, is_active boolean NOT NULL DEFAULT true, sort_order smallint NOT NULL DEFAULT 0);
CREATE TABLE ref.vehicle_service_type  (id smallint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, code citext NOT NULL UNIQUE, label text NOT NULL, is_active boolean NOT NULL DEFAULT true, sort_order smallint NOT NULL DEFAULT 0);
CREATE TABLE ref.driver_unavailability_reason (id smallint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, code citext NOT NULL UNIQUE, label text NOT NULL, is_active boolean NOT NULL DEFAULT true, sort_order smallint NOT NULL DEFAULT 0);
CREATE TABLE ref.trip_purpose          (id smallint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, code citext NOT NULL UNIQUE, label text NOT NULL, allows_self_drive boolean NOT NULL DEFAULT false, is_active boolean NOT NULL DEFAULT true, sort_order smallint NOT NULL DEFAULT 0);
CREATE TABLE ref.trip_cancel_reason    (id smallint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, code citext NOT NULL UNIQUE, label text NOT NULL, is_active boolean NOT NULL DEFAULT true, sort_order smallint NOT NULL DEFAULT 0);
CREATE TABLE ref.trip_alert_type       (id smallint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, code citext NOT NULL UNIQUE, label text NOT NULL, is_active boolean NOT NULL DEFAULT true, sort_order smallint NOT NULL DEFAULT 0);
CREATE TABLE ref.rating_role           (id smallint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, code citext NOT NULL UNIQUE, label text NOT NULL, is_active boolean NOT NULL DEFAULT true, sort_order smallint NOT NULL DEFAULT 0);  -- PASSENGER / DRIVER

-- -----------------------------------------------------------------------------
-- examiner panels (practical exams / vivas)
CREATE TABLE ref.examiner_role         (id smallint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, code citext NOT NULL UNIQUE, label text NOT NULL, is_external boolean NOT NULL, is_active boolean NOT NULL DEFAULT true, sort_order smallint NOT NULL DEFAULT 0);

-- academic operations (06c_academic_operations.sql)
CREATE TABLE ref.leave_type            (id smallint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, code citext NOT NULL UNIQUE, label text NOT NULL,
                                        attendance_status_id smallint NOT NULL REFERENCES ref.attendance_status(id),   -- how an approved leave day counts
                                        needs_document boolean NOT NULL DEFAULT false,
                                        is_active boolean NOT NULL DEFAULT true, sort_order smallint NOT NULL DEFAULT 0);
CREATE TABLE ref.prize_type            (id smallint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, code citext NOT NULL UNIQUE, label text NOT NULL, is_active boolean NOT NULL DEFAULT true, sort_order smallint NOT NULL DEFAULT 0);
CREATE TABLE ref.meeting_mode          (id smallint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, code citext NOT NULL UNIQUE, label text NOT NULL, is_active boolean NOT NULL DEFAULT true, sort_order smallint NOT NULL DEFAULT 0);
CREATE TABLE ref.section_role          (id smallint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, code citext NOT NULL UNIQUE, label text NOT NULL, is_active boolean NOT NULL DEFAULT true, sort_order smallint NOT NULL DEFAULT 0);
CREATE TABLE ref.room_feature          (id smallint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, code citext NOT NULL UNIQUE, label text NOT NULL, category citext, is_active boolean NOT NULL DEFAULT true, sort_order smallint NOT NULL DEFAULT 0);  -- category: AV / FURNITURE / ACCESS / LAB …
CREATE TABLE ref.question_difficulty   (id smallint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, code citext NOT NULL UNIQUE, label text NOT NULL, rank smallint NOT NULL UNIQUE, is_active boolean NOT NULL DEFAULT true);
CREATE TABLE ref.question_type         (id smallint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, code citext NOT NULL UNIQUE, label text NOT NULL, is_active boolean NOT NULL DEFAULT true, sort_order smallint NOT NULL DEFAULT 0);

-- academic bodies & discipline
CREATE TABLE ref.academic_body_type    (id smallint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, code citext NOT NULL UNIQUE, label text NOT NULL, is_active boolean NOT NULL DEFAULT true, sort_order smallint NOT NULL DEFAULT 0);  -- Board of Studies, Academic Council …
CREATE TABLE ref.misconduct_type       (id smallint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, code citext NOT NULL UNIQUE, label text NOT NULL, is_active boolean NOT NULL DEFAULT true, sort_order smallint NOT NULL DEFAULT 0);
CREATE TABLE ref.disciplinary_status   (id smallint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, code citext NOT NULL UNIQUE, label text NOT NULL,
                                        is_decided boolean NOT NULL,   -- a decision (and date) must be on record
                                        is_terminal boolean NOT NULL,  -- the case is closed; no further change
                                        is_active boolean NOT NULL DEFAULT true, sort_order smallint NOT NULL DEFAULT 0);
CREATE TABLE ref.disciplinary_penalty  (id smallint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, code citext NOT NULL UNIQUE, label text NOT NULL,
                                        requires_suspension boolean NOT NULL DEFAULT false,   -- must be served as a DISCIPLINARY_SUSPENSION study break
                                        is_active boolean NOT NULL DEFAULT true, sort_order smallint NOT NULL DEFAULT 0);

-- generic approval workflow (wf schema)
CREATE TABLE ref.wf_action_type        (id smallint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, code citext NOT NULL UNIQUE, label text NOT NULL,
                                        completes_step boolean NOT NULL,   -- APPROVE / SIGN move the document on
                                        closes_instance boolean NOT NULL,  -- RETURN / WITHDRAW end the round
                                        needs_note boolean NOT NULL,
                                        is_system boolean NOT NULL DEFAULT false,   -- taken by a scheduled job (no actor), only under app.system_job
                                        is_rejection boolean NOT NULL DEFAULT false,     -- closes the round for good (REJECT), as opposed to RETURN for revision
                                        returns_to_step boolean NOT NULL DEFAULT false,  -- RETURN_TO: sends the round back to an earlier level
                                        reassigns boolean NOT NULL DEFAULT false,        -- FORWARD / DELEGATE: hands the step to a named person
                                        restarts_clock boolean NOT NULL DEFAULT false,   -- the step's deadline counts from this action
                                        is_active boolean NOT NULL DEFAULT true, sort_order smallint NOT NULL DEFAULT 0);
CREATE TABLE ref.wf_approver_kind      (id smallint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, code citext NOT NULL UNIQUE, label text NOT NULL, is_active boolean NOT NULL DEFAULT true, sort_order smallint NOT NULL DEFAULT 0);  -- PERMISSION / POSITION / MANAGER / NAMED / COMMITTEE
CREATE TABLE ref.wf_self_action        (id smallint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, code citext NOT NULL UNIQUE, label text NOT NULL, is_active boolean NOT NULL DEFAULT true, sort_order smallint NOT NULL DEFAULT 0);  -- the submitter is the approver: BLOCK / SKIP
CREATE TABLE ref.wf_timeout_action     (id smallint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, code citext NOT NULL UNIQUE, label text NOT NULL, is_active boolean NOT NULL DEFAULT true, sort_order smallint NOT NULL DEFAULT 0);  -- NONE / REMIND / ESCALATE / AUTO_APPROVE / AUTO_REJECT
CREATE TABLE ref.wf_flag               (id smallint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, code citext NOT NULL UNIQUE, label text NOT NULL, is_active boolean NOT NULL DEFAULT true, sort_order smallint NOT NULL DEFAULT 0);  -- facts about a request that decide which levels apply (registered by modules)
CREATE TABLE ref.wf_notice_kind        (id smallint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, code citext NOT NULL UNIQUE, label text NOT NULL, is_active boolean NOT NULL DEFAULT true, sort_order smallint NOT NULL DEFAULT 0);
CREATE TABLE ref.wf_comment_status     (id smallint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, code citext NOT NULL UNIQUE, label text NOT NULL, is_resolved boolean NOT NULL, is_active boolean NOT NULL DEFAULT true, sort_order smallint NOT NULL DEFAULT 0);

-- ref.id_of(table, code): resolve a lookup id by code (used by seeds, tests and
-- functions; application code should cache lookups instead).
-- -----------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION ref.id_of(p_table text, p_code text)
RETURNS int LANGUAGE plpgsql STABLE AS $$
DECLARE v_id int;
BEGIN
  EXECUTE format('SELECT id FROM ref.%I WHERE code = $1', p_table) INTO v_id USING p_code;
  IF v_id IS NULL THEN
    RAISE EXCEPTION 'ref.%: unknown code %', p_table, p_code USING ERRCODE = 'no_data_found';
  END IF;
  RETURN v_id;
END $$;
